// ActiveCampaign on an API key: every operation of its v3 API (contacts, lists, tags, automations, campaigns, deals,
// accounts, ecommerce, custom objects, segments, SMS...), the SMS exports, a template's share link and event tracking.
// actions.json is generated by `bun scripts/openapi-actions.ts activecampaign`; on top, the ecommerce GraphQL API (products,
// browse sessions, recurring payments) and a way to call any v3 path the docs leave out. The person pastes their API URL
// and key in one line; calls go to their own <account>.api-us1.com. Triggers: webhooks for every event ActiveCampaign
// sends (triggers.ts), polled ones for new contacts, orders and tracked events (polls/activecampaign.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { call, specActions } from "../openapi";
import { api, parseKey } from "./api";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const ME = { method: "GET", path: "/users/me", query: [], headers: [] };

const graphql = (readOnly: boolean): OwnAction => ({
  description: readOnly
    ? "Look things up in ActiveCampaign's ecommerce GraphQL API: products in the catalog, browse sessions (abandoned browsing), recurring payments, orders. Ask for the schema with an introspection query (query { __schema { queryType { fields { name } } } }) when unsure what's there."
    : "Change things through ActiveCampaign's ecommerce GraphQL API: upsert products, orders and recurring payments in bulk, save browse sessions and add them to a cart. Ask for the schema with an introspection query first (graphql_query) when unsure of a mutation's fields.",
  readOnly,
  input: z.object({
    query: z.string().describe(readOnly ? "The GraphQL query" : "The GraphQL mutation, starting with mutation"),
    variables: z.record(z.string(), z.unknown()).optional().describe("Values for the $variables the query uses"),
  }),
  run: async ({ query, variables }: { query: string; variables?: Record<string, unknown> }, key: string) => {
    // a query can't change anything, so it runs unasked; a mutation goes through the action that asks
    if (readOnly && /^\s*mutation\b/i.test(query)) throw new AppsError("that's a mutation: use graphql_mutation, which asks first");
    const out = (await call(api, key, { method: "POST", path: "/ecom/graphql", query: [], headers: [], body: { kind: "fields", fields: [["query", "query"], ["variables", "variables"]] } }, { query, variables })) as {
      errors?: { message?: string }[];
    };
    if (out.errors?.length && !(out as { data?: unknown }).data) throw new AppsError(`ActiveCampaign: ${out.errors.map((e) => e.message).join("; ")}`);
    return out;
  },
});

const PATH = z.string().describe("The path after /api/3, like /contacts/12/contactLists or /labels");
const QUERY = z.record(z.string(), z.union([z.string(), z.number(), z.boolean()])).optional().describe('Query parameters, like {"limit": 100, "filters[name]": "VIP"}');
const raw = (method: string, path: string, query: Record<string, unknown> = {}, body: unknown, key: string) =>
  call(api, key, { method, path, query: Object.keys(query), headers: [], ...(body !== undefined && { body: { kind: "whole" as const, field: "__body" } }) }, { ...query, __body: body });
const hand: Record<string, OwnAction> = {
  graphql_query: graphql(true),
  graphql_mutation: graphql(false),
  get_api: {
    description: "Read any v3 API path the other actions don't cover (ActiveCampaign has some it doesn't document: labels, campaign link data, users by group...). Use a named action when one fits.",
    readOnly: true,
    input: z.object({ path: PATH, query: QUERY }),
    run: ({ path, query }: { path: string; query?: Record<string, unknown> }, key: string) => raw("GET", path, query, undefined, key),
  },
  call_api: {
    description: "Change something through any v3 API path the other actions don't cover. Use a named action when one fits.",
    input: z.object({
      method: z.enum(["POST", "PUT", "PATCH", "DELETE"]).describe("The HTTP method"),
      path: PATH,
      query: QUERY,
      body: z.unknown().optional().describe('The JSON body, as the API docs show it, like {"label": {"name": "VIP"}}'),
    }),
    run: ({ method, path, query, body }: { method: string; path: string; query?: Record<string, unknown>; body?: unknown }, key: string) => raw(method, path, query, body, key),
  },
};
for (const a of Object.values(hand)) {
  const run = a.run;
  // a path is joined to the person's own host, so it may not climb out of /api/3
  a.run = (input, key) => {
    if (typeof input.path === "string" && (!input.path.startsWith("/") || input.path.includes(".."))) throw new AppsError("path: start it with / and keep it inside the API, like /contacts/12");
    return run(input, key);
  };
}

export const activecampaign: OwnApp = {
  app: "activecampaign",
  name: "ActiveCampaign",
  logo: "/logos/activecampaign.svg",
  keyField: {
    label: "API URL and key",
    help: "In ActiveCampaign, open Settings (bottom left) → Developer. Copy the URL (like https://acme.api-us1.com) and the Key, and paste both on one line with a space between. The key works as your ActiveCampaign user, so Emplio can see and change whatever you can; to have Emplio react to events the moment they happen, use an admin's key.",
    placeholder: "https://acme.api-us1.com 1a2b3c4d5e6f...",
  },
  async check(key) {
    const { origin } = parseKey(key);
    const out = await call(api, key, ME, {}).catch((e) => {
      // a wrong key is a 401 or a 403 here
      throw e instanceof AppsError ? new AppsError("ActiveCampaign didn't accept that API URL and key; copy both again from Settings → Developer", true, e.message) : e;
    });
    const user = (out as { user?: { firstName?: string; lastName?: string; email?: string; username?: string } }).user ?? {};
    const who = [user.firstName, user.lastName].filter(Boolean).join(" ") || user.email || user.username || "ActiveCampaign";
    return `${who} (${new URL(origin).hostname.split(".")[0]})`;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: { ...(await specActions(new URL("./actions.json", import.meta.url), api)), ...hand },
};
